import { appendFileSync, mkdirSync, writeFileSync } from 'node:fs';
export default class ErrorReporter {
  onBegin() { mkdirSync('reports', { recursive: true }); writeFileSync('reports/errors.log', `Started ${new Date().toISOString()}\n`); }
  onTestBegin(test) { console.log(`[TEST] ${test.titlePath().join(' > ')}`); }
  onTestEnd(test, result) {
    console.log(`[${result.status === 'passed' ? 'PASS' : 'FAIL'}] ${test.title}`);
    if (result.status !== 'passed') appendFileSync('reports/errors.log', `\n[${result.status}] ${test.titlePath().join(' > ')}\n${result.errors.map(error => error.stack ?? error.message).join('\n')}\n`);
  }
}
